CREATE ROLE anon; CREATE ROLE authenticated;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth TO authenticated,anon;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated,anon;
CREATE TABLE users_master(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name text NOT NULL,email text NOT NULL UNIQUE,role text NOT NULL,is_active boolean DEFAULT true,created_at timestamptz DEFAULT now(),username text UNIQUE,password text);
CREATE TABLE departments(id bigint PRIMARY KEY,department_name text);
CREATE TABLE materials(id bigint PRIMARY KEY,material_code text,material_name text,department_id bigint REFERENCES departments(id),unit text,is_active boolean DEFAULT true,unit_cost numeric,gst_type text,gst_percentage numeric);
CREATE TABLE material_requests(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ticket_no text,material_id bigint REFERENCES materials(id),requested_qty numeric(10,2),requested_by bigint REFERENCES users_master(id),location_type text,location_name text,anacity_complaint_no text,technician_name text,remarks text,request_status text,approved_by bigint REFERENCES users_master(id),approval_date timestamptz,approved_qty numeric,issued_qty numeric DEFAULT 0,returned_qty numeric DEFAULT 0);
CREATE TABLE notifications(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id bigint,title text,message text,notification_type text,reference_id bigint,is_read boolean);
CREATE TABLE material_issue_register(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,request_id bigint,material_id bigint,ticket_no text,location_name text,location_type text,technician_name text,issued_qty numeric,unit_cost numeric,total_cost numeric,remarks text,issued_by text);
CREATE TABLE material_issues(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,request_id bigint,material_id bigint);
CREATE TABLE stock_ledger(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,material_id bigint,transaction_type text,quantity numeric,reference_no text,request_id bigint,remarks text,created_by bigint,transaction_date timestamptz);
CREATE VIEW current_stock AS SELECT m.id AS material_id,COALESCE(sum(CASE WHEN s.transaction_type='ISSUE' THEN -s.quantity ELSE s.quantity END),0) AS current_stock FROM materials m LEFT JOIN stock_ledger s ON s.material_id=m.id GROUP BY m.id;
CREATE TABLE user_permissions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id bigint,section_key text,is_allowed boolean,UNIQUE(user_id,section_key));
CREATE TABLE application_sections(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,section_key text);
CREATE FUNCTION create_material_request_notifications() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
CREATE TRIGGER trg_material_request_notifications AFTER INSERT OR UPDATE ON material_requests FOR EACH ROW EXECUTE FUNCTION create_material_request_notifications();
GRANT USAGE ON SCHEMA public TO anon,authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon,authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon,authenticated;
